to main:
    let maybe_count be ask for a number ""
    let line_count be 0
    if maybe_count is not nothing:
        set line_count to value of maybe_count

    repeat line_count times:
        let bracket_line be ask ""
        let bracket_stack be a list of ""
        remove item 1 of bracket_stack
        let line_valid be yes

        if length of bracket_line is more than 0:
            for each character_index from 1 to length of bracket_line:
                let bracket be item character_index of bracket_line
                if bracket is "(" or bracket is "[" or bracket is "{":
                    add bracket to bracket_stack
                otherwise:
                    if length of bracket_stack is 0:
                        set line_valid to no
                    otherwise:
                        let opening be item (length of bracket_stack) of bracket_stack
                        if bracket is ")" and opening is not "(":
                            set line_valid to no
                        if bracket is "]" and opening is not "[":
                            set line_valid to no
                        if bracket is "}" and opening is not "{":
                            set line_valid to no
                        remove item (length of bracket_stack) of bracket_stack

        if length of bracket_stack is more than 0:
            set line_valid to no

        if line_valid:
            say "valid"
        otherwise:
            say "invalid"

