import sys


def is_valid(sequence: str) -> bool:
    matching = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []

    for bracket in sequence:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            return False

    return not stack


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    line_count = int(first_line)
    output: list[str] = []

    for _ in range(line_count):
        sequence = sys.stdin.buffer.readline().rstrip(b"\r\n").decode("ascii")
        output.append("valid" if is_valid(sequence) else "invalid")

    if output:
        sys.stdout.write("\n".join(output) + "\n")


if __name__ == "__main__":
    main()

