use std::fmt::Write;
use std::io::{self, Read};

fn append_run(output: &mut String, start: i64, end: i64, run_len: usize) {
    if !output.is_empty() {
        output.push(',');
    }

    if run_len >= 3 {
        write!(output, "{start}-{end}").unwrap();
    } else {
        write!(output, "{start}").unwrap();
        if run_len == 2 {
            write!(output, ",{end}").unwrap();
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let count: usize = values.next().unwrap().parse().unwrap();
    if count == 0 {
        println!();
        return;
    }

    let first: i64 = values.next().unwrap().parse().unwrap();
    let mut start = first;
    let mut end = first;
    let mut run_len = 1usize;
    let mut output = String::new();

    for _ in 1..count {
        let current: i64 = values.next().unwrap().parse().unwrap();
        if end.checked_add(1) == Some(current) {
            end = current;
            run_len += 1;
        } else {
            append_run(&mut output, start, end, run_len);
            start = current;
            end = current;
            run_len = 1;
        }
    }

    append_run(&mut output, start, end, run_len);
    println!("{output}");
}

